import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  // Extract configuration with safe defaults
  const position = config.scenePosition || [0, 0, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';

  // Store original position for animation reset
  const originalPosition = new THREE.Vector3(...position);

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture through context
  const texture = ctx.textureLoader.load(imageUrl);

  // Create material for unlit textured plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transformations
  mesh.position.set(...position);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  group.add(mesh);

  // Set up event handlers
  group.userData.handlers = {
    hover: () => {
      // Kill any existing hover animation
      for (let i = timelines.length - 1; i >= 0; i--) {
        if (timelines[i]._type === 'hover') {
          timelines[i].kill();
          timelines.splice(i, 1);
        }
      }

      // Rise-in animation: y +0.15, power3.out, 0.7s
      const tl = gsap.timeline();
      tl._type = 'hover';
      tl.to(mesh.position, {
        y: originalPosition.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(tl);
    },

    unhover: () => {
      // Kill any existing hover animation
      for (let i = timelines.length - 1; i >= 0; i--) {
        if (timelines[i]._type === 'hover') {
          timelines[i].kill();
          timelines.splice(i, 1);
        }
      }

      // Return to original position
      const tl = gsap.timeline();
      tl._type = 'unhover';
      tl.to(mesh.position, {
        y: originalPosition.y,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(tl);
    },

    click: () => {
      // Press-down animation: scale 0.97, 120ms, back.out
      const tl = gsap.timeline();
      tl._type = 'click';

      tl.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0)
      .to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'back.out'
      });

      timelines.push(tl);

      // Emit navigation event
      if (config.emitEvent && ctx.emit) {
        ctx.emit(config.emitEvent, { nodeId: config.nodeId });
      }
    }
  };

  // Apply cinematic primitive: parallax-scroll
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // Dispose of three.js resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  return group;
}
